import{_ as e,c as t,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"利用規約","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/terms.md","filePath":"ja/guide/terms.md","lastUpdated":1793163976000}'),o={name:"ja/guide/terms.md"};function l(h,a,p,d,n,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="利用規約" tabindex="-1">利用規約 <a class="header-anchor" href="#利用規約" aria-label="Permalink to &quot;利用規約&quot;">​</a></h1><p>本規約は、NueZip のご利用を規定するものです。NueZip をダウンロード、インストール、または使用することにより、お客様は本規約に同意したものとみなされます。同意されない場合は、アプリケーションを使用しないでください。</p><h2 id="ライセンスと使用" tabindex="-1">ライセンスと使用 <a class="header-anchor" href="#ライセンスと使用" aria-label="Permalink to &quot;ライセンスと使用&quot;">​</a></h2><p>NueZip は、各リリースに含まれるライセンス条項の下で提供されます。お客様には、ライセンス条項に従って、お客様の Mac 上でアプリケーションを使用するための、限定的かつ非独占的、譲渡不能のライセンスが付与されます。</p><h2 id="ローカルのみの動作" tabindex="-1">ローカルのみの動作 <a class="header-anchor" href="#ローカルのみの動作" aria-label="Permalink to &quot;ローカルのみの動作&quot;">​</a></h2><p>NueZip は完全にオフラインのアプリケーションです。すべてのアーカイブ操作はお客様のデバイス上でローカルに実行されます。ファイル、メタデータ、個人データが外部サーバーに送信されることはありません。</p><h2 id="購入" tabindex="-1">購入 <a class="header-anchor" href="#購入" aria-label="Permalink to &quot;購入&quot;">​</a></h2><p>全機能のライセンスは、Mac App Store を通じた買い切りの購入で利用できます。すべての購入は Apple によって処理されます。NueZip は支払い情報を取り扱いません。再インストール時の購入復元に対応しています。</p><h2 id="ユーザーの責任" tabindex="-1">ユーザーの責任 <a class="header-anchor" href="#ユーザーの責任" aria-label="Permalink to &quot;ユーザーの責任&quot;">​</a></h2><ul><li>NueZip を適用法令に従い、合法的に使用してください。</li><li>ライセンスに違反して、アプリを逆コンパイル、リバースエンジニアリング、または改変しようとしないでください。</li><li>NueZip を使用して、アーカイブの著作権保護や DRM を回避しないでください。</li></ul><h2 id="プライバシー" tabindex="-1">プライバシー <a class="header-anchor" href="#プライバシー" aria-label="Permalink to &quot;プライバシー&quot;">​</a></h2><p>データの取り扱いとプライバシーについては、<a href="/ja/guide/privacy.html">プライバシーポリシー</a> をご確認ください。</p><h2 id="保証なし" tabindex="-1">保証なし <a class="header-anchor" href="#保証なし" aria-label="Permalink to &quot;保証なし&quot;">​</a></h2><p>NueZip はいかなる種類の保証もなく「現状有姿」で提供されます。法律で認められる最大限の範囲において、メンテナーは、商品性および特定目的への適合性を含む、明示的、黙示的、法定、またはその他のすべての保証を否認します。</p><h2 id="責任の制限" tabindex="-1">責任の制限 <a class="header-anchor" href="#責任の制限" aria-label="Permalink to &quot;責任の制限&quot;">​</a></h2><p>法律で認められる最大限の範囲において、メンテナーは、お客様によるアプリケーションの使用から生じる、間接的、付随的、特別、結果的、または懲罰的な損害について一切責任を負いません。</p><h2 id="終了" tabindex="-1">終了 <a class="header-anchor" href="#終了" aria-label="Permalink to &quot;終了&quot;">​</a></h2><p>お客様に付与された権利は、本規約に従わなかった場合、自動的に終了します。</p><h2 id="変更" tabindex="-1">変更 <a class="header-anchor" href="#変更" aria-label="Permalink to &quot;変更&quot;">​</a></h2><p>当社は本規約を随時更新する場合があります。変更後の継続的な使用は、改訂された規約の受諾とみなされます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>本規約についてのご質問は、プロジェクトのリポジトリで issue を作成してください： <code>https://github.com/nuezip/nuezip/issues</code></p><p>またはメールでお問い合わせください：nuezip@w3cub.com</p><p><em>最終更新：2026年6月14日</em></p>',24)])])}const m=e(o,[["render",l]]);export{c as __pageData,m as default};
